import { requestJson } from '../../../shared/api/httpClient'
import { ApiError } from '../../../shared/api/ApiError'

export type InventoryItem = {
  idProducto: number; codigoBarra: string | null; nombre: string; marca: string
  stock: number; precioPromedioCompra: number | null
}
export type InventoryPageData = {
  pagina: number; tamanoPagina: number; total: number; items: InventoryItem[]
}
function record(value: unknown): value is Record<string, unknown> {
  return value !== null && typeof value === 'object' && !Array.isArray(value)
}
export async function listInventory(page: number, text: string, token: string, signal: AbortSignal, filters: { idCategoria?: number; idMarca?: number } = {}): Promise<InventoryPageData> {
  const params = new URLSearchParams({ pagina: String(page), tamanoPagina: '25' })
  if (text.trim()) params.set('texto', text.trim())
  if (filters.idCategoria) params.set('idCategoria', String(filters.idCategoria))
  if (filters.idMarca) params.set('idMarca', String(filters.idMarca))
  const result = await requestJson(`/Productos/inventario?${params}`, { token, signal })
  if (!record(result) || result.pagina !== page || result.tamanoPagina !== 25 ||
    !Number.isSafeInteger(result.total) || Number(result.total) < 0 || !Array.isArray(result.items) ||
    result.items.length > 25 || result.items.length > Number(result.total) ||
    !result.items.every(item => record(item) && Number.isSafeInteger(item.idProducto) && Number(item.idProducto) > 0 &&
      (item.codigoBarra === null || typeof item.codigoBarra === 'string') &&
      typeof item.nombre === 'string' && typeof item.marca === 'string' && Number.isSafeInteger(item.stock) &&
      (item.precioPromedioCompra === null || (typeof item.precioPromedioCompra === 'number' &&
        Number.isFinite(item.precioPromedioCompra) && item.precioPromedioCompra >= 0))) ||
    new Set(result.items.map(item => item.idProducto)).size !== result.items.length)
    throw new ApiError('El servidor devolvió datos de inventario inválidos.')
  return result as InventoryPageData
}

import { useState } from 'react'

export interface InventoryOption { id: number; nombre: string }
export function InventoryLookup({ label, items, selected, loading, error, onSelect }: {
  label: string; items: InventoryOption[]; selected?: number; loading: boolean; error: string
  onSelect: (id?: number) => void
}) {
  const [query, setQuery] = useState('')
  const [open, setOpen] = useState(false)
  const normalize = (value: string) => value.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLocaleLowerCase('es').trim()
  const matches = items.filter(item => normalize(item.nombre).includes(normalize(query)))
  const id = 'inventory-' + label.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  return <div className="inventory-search inventory-lookup" onBlur={event => {
    if (!event.currentTarget.contains(event.relatedTarget)) setOpen(false)
  }}>
    <label htmlFor={id}>{label}</label>
    <input id={id} type="search" autoComplete="off" maxLength={100}
      value={query} placeholder={'Buscar ' + label.toLowerCase() + '…'}
      aria-expanded={open} aria-controls={id + '-options'}
      onFocus={() => setOpen(true)} onKeyDown={event => {
        if (event.key === 'Escape') setOpen(false)
        if (event.key === 'Enter' && matches.length === 1) {
          event.preventDefault(); setQuery(matches[0].nombre); onSelect(matches[0].id); setOpen(false)
        }
      }} onChange={event => {
        setQuery(event.target.value); setOpen(true)
        if (selected !== undefined) onSelect(undefined)
      }} />
    {open && <div id={id + '-options'} className="inventory-suggestions">
      {loading ? <p role="status">Cargando…</p> : error ? <p role="alert">{error}</p>
        : matches.length ? <ul aria-label={label + ': coincidencias'}>{matches.map(item => <li key={item.id}>
          <button type="button" onClick={() => { setQuery(item.nombre); onSelect(item.id); setOpen(false) }}>{item.nombre}</button>
        </li>)}</ul> : <p role="status">Sin coincidencias.</p>}
    </div>}
  </div>
}

import { InventoryLookup } from '../components/InventoryLookup'
import { loadCatalogLookups } from '../../catalog-lookups/api/catalogLookupsApi'
import type { CatalogLookups } from '../../catalog-lookups/api/catalogLookupsApi'
import { clearCatalogLookupCache } from '../../../shared/cache/catalogLookupCache'
import { useEffect, useState } from 'react'
import { useAuth } from '../../auth'
import { ApiError } from '../../../shared/api/ApiError'
import { RefreshButton } from '../../../shared/ui/RefreshButton'
import { useProductNames } from '../../products/hooks/useProductNames'
import { filterProductNames } from '../../products/api/searchProducts'
import { listInventory } from '../api/inventoryApi'
import type { InventoryPageData } from '../api/inventoryApi'
import './InventoryPage.css'

const money = new Intl.NumberFormat('es-GT', { style: 'currency', currency: 'GTQ', maximumFractionDigits: 6 })

export function InventoryPage() {
  const { session, logout } = useAuth()
  const [categoryId, setCategoryId] = useState<number>()
  const [brandId, setBrandId] = useState<number>()
  const [lookups, setLookups] = useState<CatalogLookups>({ categories: [], brands: [] })
  const [lookupLoading, setLookupLoading] = useState(true)
  const [lookupError, setLookupError] = useState('')
  const [data, setData] = useState<InventoryPageData | null>(null)
  const [page, setPage] = useState(1)
  const [query, setQuery] = useState('')
  const [text, setText] = useState('')
  const [revision, setRevision] = useState(0)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')
  const [suggestionsOpen, setSuggestionsOpen] = useState(false)
  const names = useProductNames(revision)
  const suggestions = filterProductNames(names.items, query)
  const token = session?.token
  const allowed = session?.user.role === 'ADMINISTRADOR'

  useEffect(() => {
    if (!token || !allowed) return
    let active = true
    async function load() {
      setLookupLoading(true); setLookupError('')
      try {
        const result = await loadCatalogLookups(token!)
        if (active) setLookups(result)
      } catch (failure) {
        if (!active) return
        if (failure instanceof ApiError && failure.status === 401) logout('La sesión ya no es válida.')
        else setLookupError(failure instanceof Error ? failure.message : 'No se pudieron cargar categorías y marcas.')
      } finally { if (active) setLookupLoading(false) }
    }
    void load()
    return () => { active = false }
  }, [token, allowed, revision, logout])

  useEffect(() => {
    if (!token || !allowed) return
    const controller = new AbortController()
    setLoading(true); setError(''); setData(null)
    void listInventory(page, text, token, controller.signal, { idCategoria: categoryId, idMarca: brandId }).then(result => {
      if (!controller.signal.aborted) setData(result)
    }).catch(failure => {
      if (controller.signal.aborted) return
      if (failure instanceof ApiError && failure.status === 401) logout('La sesión ya no es válida.')
      else setError(failure instanceof Error ? failure.message : 'No se pudo cargar el inventario.')
    }).finally(() => { if (!controller.signal.aborted) setLoading(false) })
    return () => controller.abort()
  }, [token, allowed, page, text, categoryId, brandId, revision, logout])

  if (!allowed) return null
  const pages = Math.max(1, Math.ceil((data?.total ?? 0) / 25))
  return <section className="inventory-page" aria-label="Consulta de inventario" aria-busy={loading}>
    <div className="inventory-toolbar">
      <div className="inventory-search" onBlur={event => {
        if (!event.currentTarget.contains(event.relatedTarget)) setSuggestionsOpen(false)
      }}>
      <label htmlFor="inventory-search" >Producto</label>
        <input id="inventory-search" type="search" maxLength={100} value={query}
          placeholder="Buscar producto…" aria-expanded={suggestionsOpen && query.trim().length >= 3}
          aria-controls="inventory-suggestions" onFocus={() => setSuggestionsOpen(true)}
          onKeyDown={event => {
            if (event.key === 'Escape') setSuggestionsOpen(false)
            if (event.key === 'Enter') { setText(query.trim()); setPage(1); setSuggestionsOpen(false) }
          }}
          onChange={event => {
            const value = event.target.value
            setQuery(value); setSuggestionsOpen(true)
            if (!value.trim()) { setText(''); setPage(1) }
          }} />
      {suggestionsOpen && query.trim().length >= 3 && <div id="inventory-suggestions" className="inventory-suggestions">
        {names.loading ? <p role="status">Cargando productos…</p>
          : names.error ? <p role="alert">{names.error}</p>
          : suggestions.length ? <ul aria-label="Productos sugeridos">{suggestions.map(item => <li key={item.idProducto}>
            <button type="button" onClick={() => {
              setQuery(item.nombre); setText(item.nombre); setPage(1); setSuggestionsOpen(false)
            }}>{item.nombre}</button>
          </li>)}</ul> : <p role="status">No se encontraron productos.</p>}
      </div>}
      </div>
      <InventoryLookup label="Categoría" items={lookups.categories.map(item => ({ id: item.idCategoria, nombre: item.nombre }))}
        selected={categoryId} loading={lookupLoading} error={lookupError}
        onSelect={id => { setCategoryId(id); setPage(1) }} />
      <InventoryLookup label="Marca" items={lookups.brands.map(item => ({ id: item.idMarca, nombre: item.nombre }))}
        selected={brandId} loading={lookupLoading} error={lookupError}
        onSelect={id => { setBrandId(id); setPage(1) }} />
      <RefreshButton loading={loading || names.loading || lookupLoading} label="Actualizar inventario"
        onClick={() => { clearCatalogLookupCache(); setRevision(value => value + 1) }} />
    </div>
    {loading ? <p role="status">Cargando inventario…</p> : error ? <div role="alert">
      <p>{error}</p><button type="button" onClick={() => setRevision(value => value + 1)}>Reintentar</button>
    </div> : data && <>
      <p role="status">{data.total} productos{text ? ' encontrados' : ' en inventario'}</p>
      {data.items.length ? <div className="inventory-table-scroll" role="region" aria-label="Tabla de inventario" tabIndex={0}>
        <table>
          <caption className="sr-only">Existencias y precio promedio de compra por producto</caption>
          <thead><tr><th scope="col">Código de barras</th><th scope="col">Producto</th><th scope="col">Marca</th>
            <th scope="col" className="inventory-number">Existencia</th><th scope="col" className="inventory-number">Precio Costo</th></tr></thead>
          <tbody>{data.items.map(item => <tr key={item.idProducto}>
            <td className="inventory-barcode">{item.codigoBarra || 'Sin código'}</td><td>{item.nombre}</td><td>{item.marca}</td>
            <td className="inventory-number">{item.stock.toLocaleString('es-GT')}</td>
            <td className="inventory-number">{item.precioPromedioCompra === null ? 'Sin registro' : money.format(item.precioPromedioCompra)}</td>
          </tr>)}</tbody>
        </table>
      </div> : <p>No hay productos{ text ? ' que coincidan con la búsqueda' : ' en esta página'}.</p>}
      <nav className="inventory-pagination" aria-label="Páginas de inventario">
        <button type="button" disabled={page <= 1} onClick={() => setPage(value => value - 1)}>Anterior</button>
        <span>Página {page} de {pages}</span>
        <button type="button" disabled={page >= pages || page >= 100000} onClick={() => setPage(value => value + 1)}>Siguiente</button>
      </nav>
    </>}
  </section>
}

.inventory-page { display: flex; flex-direction: column; flex: 1; gap: 18px; min-width: 0; min-height: 0; overflow: hidden; padding: 22px; background: var(--color-surface); border: 1px solid #e2e8f0; border-radius: 16px; }
.inventory-page > :not(.inventory-table-scroll) { flex-shrink: 0; }
.inventory-toolbar { display: flex; flex-wrap: wrap; align-items: end; gap: 12px; }
.inventory-search { position: relative; flex: 1; min-width: 0; }
.inventory-toolbar button.refresh-button { flex-shrink: 0; border: 0; background: transparent; padding: 8px; }
.inventory-suggestions { position: absolute; top: calc(100% + 6px); left: 0; right: 0; z-index: 5; max-height: min(320px, 40dvh); overflow-y: auto; background: var(--color-surface); border: 1px solid #e2e8f0; border-radius: 10px; box-shadow: 0 8px 20px #0f172a14; }
.inventory-suggestions ul { list-style: none; padding: 0; margin: 0; }
.inventory-suggestions p { padding: 12px; }
.inventory-suggestions li button { width: 100%; text-align: left; border: 0; border-bottom: 1px solid #e2e8f0; border-radius: 0; color: inherit; overflow-wrap: anywhere; }
.inventory-suggestions li button:hover { background: #f1f5f9; }
.inventory-toolbar label { display: grid; gap: 8px; flex: 1 1 240px; font-size: .875rem; font-weight: 600; }
.inventory-toolbar input { width: 100%; min-height: 44px; border: 1px solid #cbd5e1; border-radius: 8px; padding: 10px 12px; font: inherit; background: var(--color-surface); color: inherit; }
.inventory-page button { min-height: 44px; padding: 10px 16px; border: 1px solid #cbd5e1; border-radius: 8px; background: var(--color-surface); color: var(--color-primary); font: inherit; cursor: pointer; }
.inventory-page button:disabled { opacity: .5; cursor: default; }
.inventory-table-scroll { flex: 1; min-height: 0; overflow: auto; }
.inventory-page table { width: 100%; border-collapse: collapse; text-align: left; font-size: .9rem; }
.inventory-page th { position: sticky; top: 0; z-index: 1; background: #f1f5f9; font-weight: 650; white-space: nowrap; }
.inventory-page th, .inventory-page td { padding: 14px 16px; border-bottom: 1px solid #e2e8f0; }
.inventory-page td { min-width: 120px; }
.inventory-page .inventory-number { text-align: right; font-variant-numeric: tabular-nums; white-space: nowrap; }
.inventory-barcode { font-variant-numeric: tabular-nums; white-space: nowrap; }
.inventory-pagination { display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 12px; font-size: .875rem; }
@media (max-width: 600px) { .inventory-page { padding: 16px; } .inventory-page th, .inventory-page td { padding: 12px; } }

.inventory-toolbar .inventory-search { flex: 1 1 200px; }
.inventory-search > label { display: block; margin-bottom: 8px; }
.inventory-suggestions li button:focus-visible { outline: 2px solid var(--color-primary); outline-offset: -3px; }
@media (max-width: 600px) { .inventory-toolbar .inventory-search { flex-basis: 100%; } }
